arguments.file_text:
@using sv_6944906dcaf2404ea7e30e2ed122ff2d.Services

<div class="channel-list">
    <div class="channel-list-header">
        <h3>Channels</h3>
    </div>
    <div class="channel-list-items">
        @foreach (var channel in Channels)
        {
            <ChannelItem Channel="channel"
                         IsActive="channel.Id == ActiveChannelId"
                         OnSelected="OnChannelSelected" />
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public List<Channel> Channels { get; set; } = [];

    [Parameter]
    public int ActiveChannelId { get; set; }

    [Parameter]
    public EventCallback<Channel> OnChannelSelected { get; set; }
}

.channel-list {
    display: flex;
    flex-direction: column;
    height: 100%;
    background: #1e2024;
    border-right: 1px solid #3a3d42;
}

.channel-list-header {
    padding: 16px;
    border-bottom: 1px solid #3a3d42;
}

.channel-list-header h3 {
    margin: 0;
    font-size: 1rem;
    color: #fff;
    font-weight: 700;
}

.channel-list-items {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
}

@using sv_6944906dcaf2404ea7e30e2ed122ff2d.Services

<div class="message-area">
    <div class="message-area-header">
        <h2># @ChannelName</h2>
        <p>@ChannelDescription</p>
    </div>

    <div class="message-list" @onscroll="HandleScroll">
        @if (IsLoadingMore)
        {
            <div class="loading-indicator">Loading older messages...</div>
        }
        @foreach (var message in Messages)
        {
            <MessageItem Message="message"
                         ReplyCount="GetReplyCount(message.Id)"
                         OnOpenThread="OnOpenThread"
                         OnReact="OnReact" />
        }
    </div>

    <MessageInput Placeholder="@($"Message #{ChannelName}")"
                  ButtonText="Send"
                  OnSubmit="OnSendMessage" />
</div>

@code {
    [Parameter, EditorRequired]
    public string ChannelName { get; set; } = string.Empty;

    [Parameter]
    public string ChannelDescription { get; set; } = string.Empty;

    [Parameter, EditorRequired]
    public List<Message> Messages { get; set; } = [];

    [Parameter]
    public Dictionary<int, int> ThreadReplyCounts { get; set; } = [];

    [Parameter]
    public bool IsLoadingMore { get; set; }

    [Parameter]
    public EventCallback OnLoadMore { get; set; }

    [Parameter]
    public EventCallback<int> OnOpenThread { get; set; }

    [Parameter]
    public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }

    [Parameter]
    public EventCallback<string> OnSendMessage { get; set; }

    private int GetReplyCount(int messageId)
    {
        return ThreadReplyCounts.GetValueOrDefault(messageId, 0);
    }

    private async Task HandleScroll(EventArgs e)
    {
        // Scroll-to-top detection is handled via JS interop in production;
        // here we expose the callback for the parent to trigger pagination.
        await Task.CompletedTask;
    }
}

.message-area {
    display: flex;
    flex-direction: column;
    height: 100%;
    background: #23262b;
}

.message-area-header {
    padding: 12px 20px;
    border-bottom: 1px solid #3a3d42;
    flex-shrink: 0;
}

.message-area-header h2 {
    margin: 0;
    font-size: 1.1rem;
    color: #fff;
    font-weight: 700;
}

.message-area-header p {
    margin: 2px 0 0;
    font-size: 0.8rem;
    color: #999;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 12px 0;
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.loading-indicator {
    text-align: center;
    padding: 12px;
    color: #888;
    font-size: 0.85rem;
}

@using sv_6944906dcaf2404ea7e30e2ed122ff2d.Services

<div class="thread-panel">
    <div class="thread-header">
        <h3>Thread</h3>
        <button class="close-btn" @onclick="OnClose">✕</button>
    </div>

    <div class="thread-root-message">
        <div class="root-author">@RootMessage.Author</div>
        <div class="root-content">@RootMessage.Content</div>
    </div>

    <div class="thread-replies">
        @foreach (var reply in Replies)
        {
            <div class="thread-reply">
                <div class="reply-header">
                    <span class="reply-author">@reply.Author</span>
                    <span class="reply-time">@FormatRelativeTime(reply.SentAt)</span>
                </div>
                <div class="reply-content">@reply.Content</div>
            </div>
        }
    </div>

    <MessageInput Placeholder="Reply in thread..."
                  ButtonText="Reply"
                  OnSubmit="OnReply" />
</div>

@code {
    [Parameter, EditorRequired]
    public Message RootMessage { get; set; } = default!;

    [Parameter, EditorRequired]
    public List<Message> Replies { get; set; } = [];

    [Parameter]
    public EventCallback<string> OnReply { get; set; }

    [Parameter]
    public EventCallback OnClose { get; set; }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt;

        if (diff.TotalMinutes < 1) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        if (diff.TotalDays < 7) return $"{(int)diff.TotalDays}d ago";
        return sentAt.ToString("MMM d, yyyy");
    }
}

.thread-panel {
    display: flex;
    flex-direction: column;
    height: 100%;
    background: #1e2024;
    border-left: 1px solid #3a3d42;
}

.thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px 16px;
    border-bottom: 1px solid #3a3d42;
}

.thread-header h3 {
    margin: 0;
    font-size: 1rem;
    color: #fff;
    font-weight: 700;
}

.close-btn {
    background: none;
    border: none;
    color: #aaa;
    font-size: 1.1rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
    line-height: 1;
}

.close-btn:hover {
    background: rgba(255, 255, 255, 0.1);
    color: #fff;
}

.thread-root-message {
    padding: 12px 16px;
    border-bottom: 1px solid #3a3d42;
    background: rgba(255, 255, 255, 0.03);
}

.root-author {
    font-weight: 700;
    font-size: 0.85rem;
    color: #e0e0e0;
    margin-bottom: 4px;
}

