@page "/chat"
@using sv_6944906dcaf2404ea7e30e2ed122ff2d.Services
@inject IChatService ChatService
@rendermode InteractiveServer

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <div class="chat-sidebar">
        <ChannelList Channels="channels"
                     ActiveChannelId="activeChannelId"
                     OnChannelSelected="HandleChannelSelected" />
    </div>

    <div class="chat-main @(threadOpen ? "" : "expanded")">
        @if (activeChannel is not null)
        {
            <MessageArea ChannelName="@activeChannel.Name"
                         ChannelDescription="@activeChannel.Description"
                         Messages="messages"
                         ThreadReplyCounts="threadReplyCounts"
                         IsLoadingMore="isLoadingMore"
                         OnLoadMore="LoadMoreMessages"
                         OnOpenThread="HandleOpenThread"
                         OnReact="HandleReact"
                         OnSendMessage="HandleSendMessage" />
        }
    </div>

    @if (threadOpen && threadRootMessage is not null)
    {
        <div class="chat-thread">
            <ThreadPanel RootMessage="threadRootMessage"
                         Replies="threadReplies"
                         OnReply="HandleThreadReply"
                         OnClose="HandleCloseThread" />
        </div>
    }
</div>

@code {
    private List<Channel> channels = [];
    private Channel? activeChannel;
    private int activeChannelId;
    private List<Message> messages = [];
    private Dictionary<int, int> threadReplyCounts = [];
    private bool isLoadingMore;
    private int messageSkip;
    private const int PageSize = 30;

    private bool threadOpen;
    private Message? threadRootMessage;
    private List<Message> threadReplies = [];

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0]);
        }
    }

    private async Task HandleChannelSelected(Channel channel)
    {
        await SelectChannel(channel);
    }

    private async Task SelectChannel(Channel channel)
    {
        activeChannel = channel;
        activeChannelId = channel.Id;
        messageSkip = 0;
        messages = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        messageSkip = messages.Count;
        await ChatService.MarkChannelReadAsync(channel.Id);
        await ComputeThreadReplyCounts();
        HandleCloseThread();
    }

    private async Task LoadMoreMessages()
    {
        if (isLoadingMore || activeChannel is null)
            return;

        isLoadingMore = true;
        var older = await ChatService.GetMessagesAsync(activeChannel.Id, messageSkip, PageSize);
        if (older.Count > 0)
        {
            messages.InsertRange(0, older);
            messageSkip += older.Count;
            await ComputeThreadReplyCounts();
        }
        isLoadingMore = false;
    }

    private async Task HandleSendMessage(string content)
    {
        if (activeChannel is null)
            return;

        var message = await ChatService.SendMessageAsync(activeChannel.Id, content, null);
        messages.Add(message);
    }

    private async Task HandleOpenThread(int messageId)
    {
        var root = messages.FirstOrDefault(m => m.Id == messageId);
        if (root is null)
            return;

        threadRootMessage = root;
        threadReplies = await ChatService.GetThreadAsync(messageId);
        threadOpen = true;
    }

    private void HandleCloseThread()
    {
        threadOpen = false;
        threadRootMessage = null;
        threadReplies = [];
    }

    private async Task HandleThreadReply(string content)
    {
        if (activeChannel is null || threadRootMessage is null)
            return;

        var reply = await ChatService.SendMessageAsync(activeChannel.Id, content, threadRootMessage.Id);
        threadReplies.Add(reply);

        // Update reply count
        if (threadReplyCounts.ContainsKey(threadRootMessage.Id))
            threadReplyCounts[threadRootMessage.Id]++;
        else
            threadReplyCounts[threadRootMessage.Id] = 1;
    }

    private async Task HandleReact((int MessageId, string Emoji) reaction)
    {
        await ChatService.AddReactionAsync(reaction.MessageId, reaction.Emoji);

        var msg = messages.FirstOrDefault(m => m.Id == reaction.MessageId);
        if (msg is not null)
        {
            var existing = msg.Reactions.FirstOrDefault(r => r.Emoji == reaction.Emoji);
            if (existing is not null)
            {
                existing.Users.Add("You");
            }
            else
            {
                msg.Reactions.Add(new Reaction(reaction.Emoji, ["You"]));
            }
        }
    }

    private Task ComputeThreadReplyCounts()
    {
        threadReplyCounts = messages
            .Where(m => m.ReplyToId is not null)
            .GroupBy(m => m.ReplyToId!.Value)
            .ToDictionary(g => g.Key, g => g.Count());

        return Task.CompletedTask;
    }
}

.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    background: #23262b;
    color: #e0e0e0;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

.chat-sidebar {
    width: 20%;
    min-width: 200px;
    max-width: 280px;
    flex-shrink: 0;
}

.chat-main {
    flex: 1;
    min-width: 0;
}

.chat-main.expanded {
    flex: 1;
}

.chat-thread {
    width: 25%;
    min-width: 280px;
    max-width: 400px;
    flex-shrink: 0;
}

